using System;
using System.Linq;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
[Serializable]public class CircuitEntrant {public string id,name,modelId;public WorkshopBuild build;public float speedKph;public int paint;}
[Serializable]public class CircuitContract {public string id,eventId,playerId,playerModelId,playerName;public WorkshopBuild playerBuild;public CircuitEntrant[] rivals;public int entryFee,perRival;}
[Serializable]public class CircuitResult {public string contractId;public bool completed;public int beaten,playerMilliseconds;public int[] rivalMilliseconds;}
public static class CircuitRules {
 public const string EventId="evt_citystakes_01";public const int Entry=3000,PerRival=1000,Count=7;
 public static CircuitEntrant[] Field(string request){var builds=new[]{new WorkshopBuild{naStage=2,gearboxStage=2,tireStage=1},new WorkshopBuild{naStage=1,gearboxStage=1,tireStage=2},new WorkshopBuild{naStage=1,gearboxStage=2,induction="roots",inductionStage=1,tireStage=2},new WorkshopBuild{naStage=1,gearboxStage=2,induction="small",inductionStage=1,tireStage=2},new WorkshopBuild{naStage=1,gearboxStage=3,induction="large",inductionStage=2,tireStage=2},new WorkshopBuild{naStage=1,gearboxStage=3,induction="roots",inductionStage=2,coolingStage=1,tireStage=2},new WorkshopBuild{tireStage=2}};string[] models={"car_finch","car_coda","car_bastion","car_vector","car_coda","car_bastion","car_tempest"};string[] names={"Mara / Finch Sport","Ivo / Coda Club","Rex / Supercharged Bastion","Theo / Vector Six","Nia / Big-turbo Coda","Vera / Blown V8 Bastion","Sana / Tempest R"};float[] speeds={72,82,90,96,103,110,120};return Enumerable.Range(0,Count).Select(i=>new CircuitEntrant{id=request+":"+i,name=names[i],modelId=models[i],build=builds[i],speedKph=speeds[i],paint=i%5}).ToArray();}
 public static string ResultId(string id){var b=Guid.Parse(id).ToByteArray();b[15]^=0x40;return new Guid(b).ToString("N");}
}
public sealed class CircuitSession {
 public readonly CircuitContract Contract;public readonly TrialSession Player;public readonly TrialSession[] Rivals;public bool Resolved{get;private set;}public CircuitResult Result{get;private set;}public float Clock{get;private set;}int livePlace=8;
 public CircuitSession(CircuitContract contract,TrialDefinition route){Contract=contract;Player=new TrialSession(route);Rivals=contract.rivals.Select(_=>new TrialSession(route)).ToArray();}
 public void Tick(float dt,Vector3 playerFrom,Vector3 playerTo,Vector3[] from,Vector3[] to){if(Resolved)return;if(from.Length!=Rivals.Length||to.Length!=Rivals.Length)throw new ArgumentException("Rival count changed");Clock+=dt;Player.Tick(dt,playerFrom,playerTo);for(int i=0;i<Rivals.Length;i++)Rivals[i].Tick(dt,from[i],to[i]);int next=Math.Min(Player.NextGate,Player.Definition.checkpoints.Length-1);float distance=(playerTo-Player.Definition.checkpoints[next].Position).sqrMagnitude;livePlace=1+Enumerable.Range(0,Rivals.Length).Count(i=>Rivals[i].ValidFinish||Rivals[i].NextGate>Player.NextGate||Rivals[i].NextGate==Player.NextGate&&(to[i]-Player.Definition.checkpoints[next].Position).sqrMagnitude<distance);if(Player.ValidFinish)Finish(true);else if(Player.State==TrialState.Abandoned||Clock>600)Forfeit();}
 void Finish(bool completed){int ms=completed?Math.Max(1,(int)Math.Round(Player.Elapsed*1000)):0;int[] others=Rivals.Select(r=>r.ValidFinish?Math.Max(1,(int)Math.Round(r.Elapsed*1000)):-1).ToArray();int beaten=completed?others.Count(t=>t<0||t>ms):0;Result=new CircuitResult{contractId=Contract.id,completed=completed,beaten=beaten,playerMilliseconds=ms,rivalMilliseconds=others};Resolved=true;}
 public void Forfeit(){if(Resolved)return;Player.Abandon();Finish(false);}
 public int Position {get{if(Player.ValidFinish)return 8-Result.beaten;return livePlace;}}
}
public static class CircuitLedger {
 static void Need(bool ok,string why){if(!ok)throw new InvalidOperationException(why);}
 public static bool Pending(FleetState f)=>f.circuit!=null&&!string.IsNullOrEmpty(f.circuit.id);
 public static void Apply(FleetState f,TuneReceipt r,string profileId){Need(r.pathId=="circuit_v10"&&r.stage==0,"Invalid circuit receipt");if(r.kind=="circuit_open"){var c=JsonUtility.FromJson<CircuitContract>(r.fleetJson);Need(!f.HasPending&&c!=null&&Guid.TryParse(c.id,out _)&&c.id==r.transactionId&&c.eventId==CircuitRules.EventId&&r.partId==c.eventId&&r.configId==c.playerId&&c.entryFee==CircuitRules.Entry&&c.perRival==CircuitRules.PerRival&&r.credits==c.entryFee,"Invalid circuit entry terms");Need(c.playerId==f.selectedId&&EngineInventoryLedger.HasEngine(f,c.playerId),"Selected car must have an engine");Need(c.playerId==FleetLedger.Loaner||FleetLedger.Find(f,c.playerId).owner=="player","Circuit car is not owned");string model=c.playerId==FleetLedger.Loaner?"car_finch":VehicleLineup.Model(FleetLedger.Find(f,c.playerId));Need(c.playerModelId==model&&JsonUtility.ToJson(c.playerBuild)==JsonUtility.ToJson(FleetLedger.Active(f)),"Circuit entry car/build changed");Need(c.rivals!=null&&c.rivals.Length==7,"Circuit needs seven rivals");for(int i=0;i<7;i++){var e=c.rivals[i];Need(e!=null&&e.id==c.id+":"+i&&!string.IsNullOrWhiteSpace(e.name)&&e.speedKph>=20&&e.speedKph<=140,"Invalid frozen circuit rival");WorkshopCatalog.ForBuild(e.modelId,e.build).Resolve(e.build);}f.circuit=c;return;}
 Need(r.kind=="circuit_result"&&Pending(f),"No committed circuit to settle");var d=f.circuit;var result=JsonUtility.FromJson<CircuitResult>(r.fleetJson);Need(result!=null&&result.contractId==d.id&&r.transactionId==CircuitRules.ResultId(d.id)&&r.configId==d.id&&r.partId==(result.completed?"finish":"forfeit")&&result.rivalMilliseconds!=null&&result.rivalMilliseconds.Length==7,"Invalid circuit result identity");Need(result.rivalMilliseconds.All(t=>t==-1||t>0),"Invalid circuit finish time");int beaten=result.completed?result.rivalMilliseconds.Count(t=>t<0||t>result.playerMilliseconds):0;Need((result.completed?result.playerMilliseconds>0:result.playerMilliseconds==0)&&result.beaten==beaten&&beaten>=0&&beaten<=7&&r.credits== -checked(beaten*d.perRival),"Circuit reward disagrees with frozen finish order");f.circuit=null;
 }
}
}
